"""SYNTHETIC demonstration signals. These are generated by code and are NOT measured ocean data.
Every function returns (samples, fs) and the UI must label the result 'synthetic'.
They are crude caricatures of each category, used for demos and for unit-testing the pipeline."""
from __future__ import annotations
import numpy as np
from scipy.signal import butter, sosfilt

CATEGORIES = ["Biological", "Vessel", "Ambient", "Impulsive", "Communication", "Mixed"]


def _norm(x):
    x = x - np.mean(x)
    return x / (np.max(np.abs(x)) + 1e-12)


def _bp(x, fs, lo, hi, order=4):
    return sosfilt(butter(order, [lo, hi], btype="band", fs=fs, output="sos"), x)


def dolphin_whistle(fs=48000, dur=1.0, rng=None):
    rng = rng or np.random.default_rng(0)
    t = np.arange(int(fs * dur)) / fs
    f = 6000 + 6000 * (0.5 - 0.5 * np.cos(2 * np.pi * t / dur * rng.uniform(0.8, 1.4)))
    ph = 2 * np.pi * np.cumsum(f) / fs
    x = np.hanning(len(t)) * (np.sin(ph) + 0.3 * np.sin(2 * ph))
    return _norm(x + 0.01 * rng.normal(size=len(t))), fs


def dolphin_clicks(fs=96000, dur=1.0, rng=None):
    rng = rng or np.random.default_rng(0)
    x = 0.01 * rng.normal(size=int(fs * dur))
    for t0 in np.arange(0.05, dur - 0.05, rng.uniform(0.03, 0.06)):
        i = int(t0 * fs); n = int(0.0002 * fs)
        tt = np.arange(n) / fs
        x[i:i + n] += np.exp(-tt * 20000) * np.sin(2 * np.pi * 40000 * tt) if fs >= 100000 else np.exp(-tt * 20000) * np.sin(2 * np.pi * 15000 * tt)
    return _norm(x), fs


def whale_moan(fs=4000, dur=6.0, rng=None):
    rng = rng or np.random.default_rng(0)
    t = np.arange(int(fs * dur)) / fs
    f = 60 + 40 * np.sin(2 * np.pi * t / dur / 2)
    x = np.sin(2 * np.pi * np.cumsum(f) / fs) * np.hanning(len(t))
    return _norm(x + 0.03 * rng.normal(size=len(t))), fs


def ship_noise(fs=16000, dur=4.0, rng=None, small=False):
    rng = rng or np.random.default_rng(0)
    n = int(fs * dur); t = np.arange(n) / fs
    broad = _bp(rng.normal(size=n), fs, 20, 2000 if small else 800)
    f0 = 45.0 if not small else 90.0
    tones = sum(a * np.sin(2 * np.pi * k * f0 * t + rng.uniform(0, 6.28)) for k, a in ((1, 1.0), (2, 0.6), (3, 0.4)))
    mod = 1 + 0.3 * np.sin(2 * np.pi * (2.0 if not small else 7.0) * t)      # propeller blade-rate modulation
    return _norm(0.5 * broad * mod / np.std(broad) + 0.15 * tones), fs


def ambient_wind(fs=16000, dur=4.0, rng=None):
    rng = rng or np.random.default_rng(0)
    w = rng.normal(size=int(fs * dur))
    F = np.fft.rfft(w); f = np.fft.rfftfreq(len(w), 1 / fs); f[0] = f[1]
    return _norm(np.fft.irfft(F / np.sqrt(f), len(w))), fs                    # ~1/f power: pink-like


def rain(fs=32000, dur=3.0, rng=None):
    rng = rng or np.random.default_rng(0)
    n = int(fs * dur); x = 0.2 * _bp(rng.normal(size=n), fs, 1000, 12000)
    for i in rng.integers(0, n - 400, int(120 * dur)):
        tt = np.arange(400) / fs
        x[i:i + 400] += rng.uniform(0.2, 1.0) * np.exp(-tt * 1500) * np.sin(2 * np.pi * rng.uniform(3000, 9000) * tt)
    return _norm(x), fs


def impulsive_event(fs=4000, dur=6.0, rng=None):
    rng = rng or np.random.default_rng(0)
    n = int(fs * dur); x = 0.01 * rng.normal(size=n)
    i = int(rng.uniform(1.5, 3) * fs); tt = np.arange(n - i) / fs
    x[i:] += np.exp(-tt * 6) * _bp(rng.normal(size=n - i), fs, 5, 100)
    return _norm(x), fs


def bpsk_burst(fs=48000, dur=1.0, fc=12000.0, rate=500, rng=None):
    rng = rng or np.random.default_rng(0)
    nb = int(dur * rate); bits = rng.integers(0, 2, nb); sps = int(fs / rate)
    sym = np.repeat(2.0 * bits - 1, sps); t = np.arange(len(sym)) / fs
    x = np.zeros(int(fs * dur)); x[:len(sym)] = sym * np.cos(2 * np.pi * fc * t)
    return _norm(x + 0.01 * rng.normal(size=len(x))), fs


def mixed_whistle_over_ship(fs=48000, dur=1.5, rng=None):
    rng = rng or np.random.default_rng(0)
    w, _ = dolphin_whistle(fs, dur, rng); s, _ = ship_noise(fs, dur, rng)
    return _norm(0.6 * w + 0.8 * s), fs


GENERATORS = {"Biological": dolphin_whistle, "Vessel": ship_noise, "Ambient": ambient_wind, "Impulsive": impulsive_event,
              "Communication": bpsk_burst, "Mixed": mixed_whistle_over_ship}
EXTRA = {"Biological (clicks)": dolphin_clicks, "Biological (whale-like moan)": whale_moan, "Vessel (small boat)": lambda fs=16000, dur=4.0, rng=None: ship_noise(fs, dur, rng, True),
         "Ambient (rain-like)": rain}


def generate(name, seed=0):
    g = GENERATORS.get(name) or EXTRA[name]
    return g(rng=np.random.default_rng(seed))
